/**
 * Continuous effects ready to be applied: the ones generated by the CURRENT abilities of objects (static abilities are live, CR 611.3a), the resolved
 * ones stored in GameState.continuousEffects (CR 611.2) and the ones the rules generate from counters (CR 122.1a-b, 613.4c). Owner: WP9.
 * Contract: statics/api.ts#LiveEffect.
 *
 * What a static ability stores: nothing. At the start of every layer the abilities each object has RIGHT THEN (after the layers before it, so an ability
 * granted in layer 6 produces layer 7 effects and one removed in layer 6 produces none) are turned into `LiveEffect`s. An effect that has already started to
 * apply in an earlier layer is carried by `computeAll` (CR 613.6), so it is not generated again here.
 */
import type { AbilityDef, KeywordAbilityDef, Layer, Modification } from '../types/ability';
import type { CardDef } from '../types/card';
import type { ObjectId } from '../types/ids';
import type { ContinuousEffectRec, GameObject, GameState } from '../types/state';
import type { Chars } from '../rules/characteristics';
import { expansionOf } from './abilities';
import { layoutExpansion } from './levels';
import type { LiveEffect } from './api';
import { evalCondition, type EvalCx } from './match';
import { KEYWORD_COUNTERS } from './mods';
import { isMergedObject } from './merge';
import { suspectedPresent } from './suspect';
import { honePresent } from './hone';
import { whileObjectHolds } from './while-object';

const KEYWORD_COUNTER_SET: ReadonlySet<string> = new Set(KEYWORD_COUNTERS);

/** `StaticEffect` discriminators (`s`) that live static abilities and resolved effects can carry (capabilities `static:<s>`, design 5.2). */
export const STATIC_KINDS: Readonly<Record<string, true>> = { continuous: true };

/** The number in an id (`o97` -> 97, `e12` -> 12, `ctr:o5` -> 5): ids are compared as numbers, so `e9` comes before `e10`. 0 when there is none. */
export const numOf = (id: string): number => {
  const m = /(\d+)(?!.*\d)/.exec(id);
  return m ? Number(m[1]) : 0;
};

/** Does this effect have a modification in the layer? */
export const hasLayer = (e: LiveEffect, layer: Layer): boolean => e.effect.mods.some((m) => m.layer === layer);

/** Effects generated by the static abilities of objects, for one layer, given the characteristics computed so far. */
export function staticEffectsOf(s: GameState, all: Map<ObjectId, Chars>, layer: Layer): LiveEffect[] {
  const out: LiveEffect[] = [];
  for (const [id, c] of all) {
    const o = s.objects[id];
    if (!o || o.phasedOut || o.kind === 'ability') continue; // CR 702.26b; an ability on the stack has no abilities of its own
    let cx: EvalCx | undefined;
    for (let pos = 0; pos < c.abilities.length; pos++) {
      const a = c.abilities[pos]!;
      const d = a.def;
      if (d.kind !== 'static') continue;
      const inZone = (d.zone ?? ['battlefield']).includes(o.zone); // CR 113.6, 604.5
      // r5-static (CR 611.3a): while the condition is false, the ability has its `otherwise` effects instead (indexed after `effects`)
      let holds: boolean | undefined;
      const conditionHolds = (): boolean => {
        if (!d.condition) return true;
        cx ??= { s, all, source: id, controller: c.controller };
        return (holds ??= evalCondition(cx, d.condition));
      };
      const listed = d.otherwise === undefined ? d.effects : [...d.effects, ...d.otherwise];
      listed.forEach((e, i) => {
        if (e.s !== 'continuous' || !e.mods.some((m) => m.layer === layer)) return;
        if (!inZone && e.cda !== true) return; // CR 604.3: characteristic-defining abilities function everywhere
        if (d.condition && conditionHolds() !== i < d.effects.length) return; // CR 611.3a: "as long as" wraps every effect
        out.push({
          id: `live:${id}:${a.key}:${i}`,
          source: { id, zone: o.zone },
          origin: { source: { id, zone: o.zone }, abilityKey: a.key, effectIndex: i },
          // CR 613.7a: the object's timestamp, or the granting effect's if that is later.
          timestamp: a.grantedAt !== undefined && a.grantedAt > o.timestamp ? a.grantedAt : o.timestamp,
          controller: c.controller,
          rank: [0, numOf(id), a.grantedAt ?? -1, pos, i], // CR 613.7a: the object's own abilities before the granted ones, each group in its order
          effect: e,
        });
      });
    }
  }
  return out;
}

/** Is the "for as long as" duration of a resolved effect over? (The effect is also removed from the state by the code that ends durations; this only keeps a stale one from applying.) */
function durationOver(s: GameState, source: LiveEffect['source'], d: ContinuousEffectRec['duration'], attachedTo?: string): boolean {
  if (d.d === 'whileObject') return !whileObjectHolds(s, d); // std-rx32 (CR 611.2b): the object the effect is about
  if (d.d !== 'whileSource') return false;
  const o = source ? s.objects[source.id] : undefined;
  if (!o || !source || o.zone !== source.zone) return true; // CR 611.2b, 400.7
  switch (d.as) {
    case 'controlled': return false; // judged by computeAll with the controller after layer 2 (`endsUnlessControlled`, CR 611.2b, 613.1b)
    // WP15 INTERFACE CHANGE (review): "remains attached to it": attached to something else than as the effect began is over too (CR 301.5c)
    case 'attached': return attachedTo !== undefined ? o.attachedTo !== attachedTo : o.attachedTo === undefined;
    case 'tapped': return !o.tapped;
    default: return false; // 'onBattlefield' is the zone test above
  }
}

/** Effects created by resolved spells and abilities (typed `ContinuousEffectRec`s; milestone 4's legacy records are ignored until transition T1 ends). */
export function resolvedEffects(s: GameState): LiveEffect[] {
  const out: LiveEffect[] = [];
  for (const rec of s.continuousEffects) {
    if (rec.effect.s !== 'continuous') continue;
    if (durationOver(s, rec.source, rec.duration, rec.attachedTo)) continue;
    const e: LiveEffect = { id: rec.id, source: rec.source, timestamp: rec.timestamp, controller: rec.controller, rank: [1, numOf(rec.id)], effect: rec.effect };
    if (rec.duration.d === 'whileSource' && rec.duration.as === 'controlled' && rec.source) e.endsUnlessControlled = { object: rec.source.id, by: rec.controller };
    if (rec.copy) e.copy = rec.copy; // M6-0 (m6 design 2.5): a copy effect's snapshot (M6-2)
    if (rec.asEntry) e.asEntry = true; // M6-0: an "as enters" P/T effect applied in 1a (CR 613.2a; M6-2)
    out.push(e);
  }
  return out;
}

// ---- counters (CR 122.1a-b, 613.4c, 613.7c) -----------------------------------------------------------------------------------

/**
 * The modifications the counters on an object make: a keyword counter grants its keyword (layer 6, CR 122.1b) and +1/+1 / -1/-1 counters change power and
 * toughness (layer 7c, CR 122.1a, 613.4c; in every zone: a creature card outside the battlefield has them too). The engine does not track a timestamp per counter (CR 613.7c), so the
 * effect takes the object's; the changes are additions, so their order among the other layer 7c effects is not observable.
 */
export function counterMods(o: GameObject, keep?: (kind: string) => boolean): Modification[] {
  const bag = o.counters;
  let mods: Modification[] | undefined;
  let present: string[] | undefined;
  for (const k in bag) if (KEYWORD_COUNTER_SET.has(k) && (bag[k] ?? 0) > 0 && (keep === undefined || keep(k))) (present ??= []).push(k); // almost always nothing at all, or loyalty / +1/+1
  if (present) {
    present.sort((x, y) => KEYWORD_COUNTERS.indexOf(x) - KEYWORD_COUNTERS.indexOf(y)); // a fixed order, whatever order the counters were put on
    const add: AbilityDef[] = [];
    for (const k of present) {
      const times = k === 'exalted' ? bag[k]! : 1; // CR 702.83b: each instance of exalted triggers separately
      for (let i = 0; i < times; i++) add.push({ kind: 'keyword', text: k, keyword: k });
    }
    (mods ??= []).push({ layer: 6, add });
  }
  let power = (bag['+1/+1'] ?? 0) - (bag['-1/-1'] ?? 0); // CR 704.5q makes the two cancel; until then the sum is the same
  let toughness = power;
  // std-rx17: every other +X/+Y counter (+1/+0, -0/-1, +2/+2, ...) changes power and toughness the same way (CR 122.1a); the
  // kinds are named by their numbers, so the sign is read from the name. Only +1/+1 and -1/-1 annihilate (CR 704.5q).
  for (const k in bag) {
    if (k === '+1/+1' || k === '-1/-1') continue;
    const n = bag[k] ?? 0;
    const m = n > 0 ? NUMERIC_PT_COUNTER.exec(k) : null;
    if (m) { power += n * Number(m[1]); toughness += n * Number(m[2]); }
  }
  if (power !== 0 || toughness !== 0) (mods ??= []).push({ layer: '7c', power, toughness }); // CR 122.1a: on a creature or a creature card in any zone (an object with no power is left alone)
  return mods ?? NO_MODS;
}

/** std-rx17: a counter kind named by fixed numbers, "+1/+0", "-0/-1" (CR 122.1a); the groups are the signed power and toughness changes. */
export const NUMERIC_PT_COUNTER = /^([+-]\d+)\/([+-]\d+)$/;

const NO_MODS: Modification[] = Object.freeze([]) as unknown as Modification[];

/** The rule-generated effects of counters, one per object that has any. */
export function counterEffects(s: GameState): LiveEffect[] {
  const out: LiveEffect[] = [];
  for (const id of Object.keys(s.objects)) {
    const o = s.objects[id]!;
    // r4-fxb (CR 122.1b, 613.7c): a keyword counter put on after the object got its timestamp gives its keyword with the counter's own timestamp, so an effect
    // that began between the two ("loses all abilities", then "put a flying counter on that creature") does not take it away
    const stamps = o.counterStamps;
    const late = (k: string): boolean => stamps !== undefined && Object.hasOwn(stamps, k) && stamps[k]! > o.timestamp;
    const mods = stamps === undefined ? counterMods(o) : counterMods(o, (k) => !late(k));
    const affects = { ref: 'fixed' as const, objects: [{ id, zone: o.zone }] };
    if (mods.length > 0) {
      out.push({ id: `ctr:${id}`, source: { id, zone: o.zone }, timestamp: o.timestamp, controller: o.controller, rank: [0, numOf(id), -1, -1, 0], effect: { s: 'continuous', affects, mods } });
    }
    if (stamps === undefined) continue;
    for (const k of Object.keys(stamps).sort()) {
      if (!late(k) || (o.counters[k] ?? 0) <= 0) continue;
      const times = k === 'exalted' ? o.counters[k]! : 1; // CR 702.83b
      const add: AbilityDef[] = Array.from({ length: times }, () => ({ kind: 'keyword', text: k, keyword: k }) as AbilityDef);
      out.push({ id: `ctr:${id}:${k}`, source: { id, zone: o.zone }, timestamp: stamps[k]!, controller: o.controller, rank: [0, numOf(id), -1, -1, 0], effect: { s: 'continuous', affects, mods: [{ layer: 6, add }] } });
    }
  }
  return out;
}

// ---- Which states need the layer system at all? --------------------------------------------------------------------------------

const KW_CTX = { granted: false, faceName: '', types: [] as string[], keyPrefix: 'k:0:0' };

/** Where a definition can generate continuous effects from: nowhere, the zones its static abilities function in, or everywhere (a characteristic-defining ability). */
interface DefInfo {
  generates: boolean;
  anyZone: boolean;
  zones: ReadonlySet<string>;
}
const DEF_INFO = new WeakMap<CardDef, DefInfo>();
const NO_INFO: DefInfo = { generates: false, anyZone: false, zones: new Set() };

function scanAbility(a: AbilityDef, into: { generates: boolean; anyZone: boolean; zones: Set<string> }): void {
  if (a.kind === 'static') {
    const fx = [...a.effects, ...(a.otherwise ?? [])].filter((e) => e.s === 'continuous'); // r5-static: and the `otherwise` effects
    if (fx.length === 0) return;
    into.generates = true;
    for (const z of a.zone ?? ['battlefield']) into.zones.add(z);
    if (fx.some((e) => e.s === 'continuous' && e.cda === true)) into.anyZone = true; // CR 604.3
  } else if (a.kind === 'keyword') {
    for (const x of expansionOf(a as KeywordAbilityDef, KW_CTX)) scanAbility(x, into);
  } else {
    for (const p of layoutExpansion(a)) scanAbility(p.def, into); // M6-6 INTERFACE CHANGE: a Class level, leveler bracket or Case (statics/levels.ts)
  }
}

/** Can any face of this definition generate a continuous effect (a static ability with one, or a keyword that expands into one), and from which zones? Memoized per definition. */
export function defInfo(def: CardDef): DefInfo {
  let v = DEF_INFO.get(def);
  if (!v) {
    const into = { generates: false, anyZone: false, zones: new Set<string>() };
    for (const f of def.faces) for (const a of f.abilities) scanAbility(a, into);
    v = into.generates ? into : NO_INFO;
    DEF_INFO.set(def, v);
  }
  return v;
}

export const defMayGenerateEffects = (def: CardDef): boolean => defInfo(def).generates;

/** Is some definition of this game's map one whose effects can come from outside the battlefield? (Then every object must be looked at, not just the permanents.) */
const EXOTIC = new WeakMap<GameState['defs'], boolean>();
function anyOffBattlefield(defs: GameState['defs']): boolean {
  let v = EXOTIC.get(defs);
  if (v === undefined) {
    v = false;
    for (const k in defs) {
      const i = defInfo(defs[k]!);
      if (i.generates && (i.anyZone || [...i.zones].some((z) => z !== 'battlefield'))) { v = true; break; }
    }
    EXOTIC.set(defs, v);
  }
  return v;
}

interface SourcesMemo {
  object: number;
  effect: number;
  ceLength: number;
  ceLast: string;
  battlefield: number;
  command: number;
  /** M6-9: a merge changes none of the counts above, but takes a timestamp (CR 730.2a). */
  timestamp: number;
  value: boolean;
}
const SOURCES = new WeakMap<GameState, SourcesMemo>();

/**
 * Can some effect of this state change what any object is, beyond what its own counters and abilities say? False for the vast majority of states (no static
 * ability with a continuous effect in the game, no resolved continuous effect): then `getChars` computes one object on its own, without the layer system.
 *
 * It only says "no" when no object that is where its static abilities function has a definition that could generate an effect (definitions never change, a
 * zone change makes a new object with a new id, so the answer can change only when `counters.object`, `counters.effect`, the list of effects or the number of
 * permanents does), and it is memoized per state with that key (compared field by field: this runs on every `getChars` call). A state edited by hand in a way none of those notice
 * (a test that pushes an object whose id did not come from the counter) is the one thing it cannot see.
 */
export function layerSourcesPresent(s: GameState): boolean {
  const ce = s.continuousEffects;
  const ceLast = ce.length > 0 ? ce[ce.length - 1]!.id : '';
  // std-ra (CR 122.1, 613.4c): hone counters on an Equipment pump the creature it is attached to (statics/hone.ts). Putting a counter takes no timestamp, so the
  // memo below would not see it: read before it
  if (honePresent(s)) return true;
  const hit = SOURCES.get(s);
  if (hit && hit.object === s.counters.object && hit.effect === s.counters.effect && hit.ceLength === ce.length && hit.ceLast === ceLast
    && hit.battlefield === s.zones.battlefield.length && hit.command === s.zones.command.length && hit.timestamp === s.counters.timestamp) return hit.value;
  let value = ce.some((e) => e.effect.s === 'continuous');
  // M6-9 (m6 design 3.7): a merged permanent has the abilities of every component (CR 702.140e), which no single definition shows: the layer system computes it
  if (!value) value = s.zones.battlefield.some((id) => { const o = s.objects[id]; return o !== undefined && isMergedObject(o); });
  // FAST5X E12 (CR 701.60c): a suspected permanent has menace and "can't block" from a rule-generated layer 6 effect (statics/suspect.ts). Becoming suspected
  // or no longer suspected takes a timestamp, so the memo key below sees it.
  if (!value) value = suspectedPresent(s);
  if (!value && !anyOffBattlefield(s.defs)) {
    // Every static ability of every definition in this game functions on the battlefield only: look at the permanents.
    for (const id of s.zones.battlefield) {
      const o = s.objects[id];
      const def = o && s.defs[o.defId];
      if (def && defInfo(def).generates) { value = true; break; }
    }
  } else if (!value) {
    for (const id in s.objects) {
      const o = s.objects[id]!;
      const def = s.defs[o.defId];
      if (!def) continue;
      const i = defInfo(def);
      if (i.generates && (i.anyZone || i.zones.has(o.zone))) { value = true; break; }
    }
  }
  SOURCES.set(s, { object: s.counters.object, effect: s.counters.effect, ceLength: ce.length, ceLast, battlefield: s.zones.battlefield.length, command: s.zones.command.length, timestamp: s.counters.timestamp, value });
  return value;
}
